import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        // Encode each event as time * 4 + (delta + 1) so one primitive sort orders by time.
        long[] events = new long[2 * n];
        for (int i = 0; i < n; i++) {
            long l = nextLong(), h = nextLong();
            events[2 * i] = l * 4 + 2;
            events[2 * i + 1] = (h + 1) * 4;
        }
        Arrays.sort(events);
        long current = 0, best = 0, answer = 0;
        int i = 0;
        while (i < events.length) {
            long t = events[i] >> 2;
            while (i < events.length && (events[i] >> 2) == t) current += (events[i++] & 3) - 1; // merge same time
            if (current > best) {
                best = current;
                answer = t;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"sort"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n := int(nextInt())
	type event struct{ t, d int64 }
	events := make([]event, 0, 2*n)
	for i := 0; i < n; i++ {
		l, h := nextInt(), nextInt()
		events = append(events, event{l, 1}, event{h + 1, -1})
	}
	sort.Slice(events, func(i, j int) bool { return events[i].t < events[j].t })
	var current, best, answer int64
	for i := 0; i < len(events); {
		t := events[i].t
		for i < len(events) && events[i].t == t { // merge same time
			current += events[i].d
			i++
		}
		if current > best {
			best, answer = current, t
		}
	}
	w.WriteString(strconv.FormatInt(answer, 10) + "\n")
}
